/**
 * Read an `mxGraphModel` page back into the small structure the tool and the
 * preview renderer work on: vertices, edges, and their styles.
 *
 * This is deliberately tolerant rather than a conforming XML parser. draw.io
 * documents are generated by draw.io itself, the model tool, and the embedded
 * editor, and a page that opens in draw.io must stay usable here too, so
 * unparseable fragments are kept as text instead of failing the page.
 *
 * @module @sorarisu/dsh-drawio/lib/drawio-model
 */
import { firstPageModel, findElement, readAttribute, unescapeXml } from './drawio-xml.js'

/** Parse one `style="a=b;c=d"` string into a map. */
export function parseStyle(style) {
  const map = {}
  if (typeof style !== 'string') return map
  for (const part of style.split(';')) {
    if (part.length === 0) continue
    const equals = part.indexOf('=')
    if (equals === -1) map[part.trim()] = true
    else map[part.slice(0, equals).trim()] = part.slice(equals + 1).trim()
  }
  return map
}

/** Serialize a style map back into draw.io's `key=value;` form. */
export function formatStyle(map) {
  return Object.entries(map)
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => (value === true ? `${key};` : `${key}=${value};`))
    .join('')
}

/** Every `<mxCell …>` start tag of one page body, in document order. */
function cellTags(model) {
  const root = findElement(model, 'root')
  if (root === undefined) return []
  const inner = model.slice(root.innerStart, root.innerEnd)
  const tags = []
  const pattern = /<mxCell\b/gu
  let match
  while ((match = pattern.exec(inner)) !== null) {
    const start = match.index
    const end = inner.indexOf('>', start)
    if (end === -1) break
    const body = inner.slice(start + '<mxCell'.length, end)
    const selfClosing = inner[end - 1] === '/'
    const elementEnd = selfClosing
      ? end + 1
      : (() => {
          const close = inner.indexOf('</mxCell>', end)
          return close === -1 ? end + 1 : close + '</mxCell>'.length
        })()
    const tail = selfClosing ? '' : inner.slice(end + 1, elementEnd)
    tags.push({
      body: body.replace(/\/$/u, ''),
      inner: tail,
      selfClosing,
      text: inner.slice(start, elementEnd),
      attributes: readAttributesOf(body),
    })
    pattern.lastIndex = elementEnd
  }
  return tags
}

/** Attribute map of one start-tag body (duplicated locally to avoid a cycle). */
function readAttributesOf(body) {
  const attributes = {}
  const pattern = /([\w:-]+)\s*=\s*"([^"]*)"/gu
  let match
  while ((match = pattern.exec(body)) !== null) {
    attributes[match[1]] = unescapeXml(match[2])
  }
  return attributes
}

/** Parsed `<mxGeometry>` of one cell, including edge waypoints. */
function geometryOf(attributes, inner) {
  const vertex = attributes.vertex === '1'
  const edge = attributes.edge === '1'
  if (vertex) {
    const geometry = findElement(inner, 'mxGeometry')
    if (geometry === undefined) return { x: 0, y: 0, width: 120, height: 40 }
    const tag = inner.slice(geometry.startTagStart, geometry.startTagEnd + 1)
    return {
      x: numberOr(readAttribute(tag, 'x'), 0),
      y: numberOr(readAttribute(tag, 'y'), 0),
      width: numberOr(readAttribute(tag, 'width'), 120),
      height: numberOr(readAttribute(tag, 'height'), 40),
    }
  }
  if (edge) {
    const points = []
    const array = findElement(inner, 'Array')
    if (array !== undefined) {
      const list = inner.slice(array.innerStart, array.innerEnd)
      const pattern = /<mxPoint\b[^>]*>/gu
      let match
      while ((match = pattern.exec(list)) !== null) {
        points.push({
          x: numberOr(readAttribute(match[0], 'x'), 0),
          y: numberOr(readAttribute(match[0], 'y'), 0),
        })
      }
    }
    const startTag = /<mxPoint\b[^>]*as="sourcePoint"[^>]*>/u.exec(inner)
    const endTag = /<mxPoint\b[^>]*as="targetPoint"[^>]*>/u.exec(inner)
    return {
      points,
      sourcePoint: startTag === null
        ? undefined
        : {
            x: numberOr(readAttribute(startTag[0], 'x'), 0),
            y: numberOr(readAttribute(startTag[0], 'y'), 0),
          },
      targetPoint: endTag === null
        ? undefined
        : {
            x: numberOr(readAttribute(endTag[0], 'x'), 0),
            y: numberOr(readAttribute(endTag[0], 'y'), 0),
          },
    }
  }
  return { x: 0, y: 0, width: 0, height: 0 }
}

/** A finite number, or the fallback. */
function numberOr(value, fallback) {
  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : fallback
}

/**
 * Read one page into vertices, edges, and the raw tag text each came from.
 *
 * @param {string} xml - any accepted document input.
 * @returns {{
 *   nodes: Array<{ id: string, label: string, style: Record<string, unknown>, x: number, y: number, width: number, height: number, parent?: string, text: string }>,
 *   edges: Array<{ id: string, label: string, source?: string, target?: string, points: Array<{ x: number, y: number }>, style: Record<string, unknown>, text: string }>,
 *   layers: Array<{ id: string, name?: string }>,
 *   model: string,
 * }}
 */
export function readDiagram(xml) {
  const model = firstPageModel(xml)
  const nodes = []
  const edges = []
  const layers = []
  for (const tag of cellTags(model)) {
    const attributes = tag.attributes
    const id = attributes.id
    if (id === undefined) continue
    if (id === '0') continue
    if (attributes.vertex !== '1' && attributes.edge !== '1') {
      // A layer (`1`) or a group/parent cell.
      if (id === '1' || attributes.parent === '0') layers.push({ id, name: attributes.value })
      continue
    }
    const label = attributes.value ?? ''
    if (attributes.vertex === '1') {
      const geometry = geometryOf(attributes, tag.inner)
      nodes.push({
        id,
        label,
        style: parseStyle(attributes.style),
        x: geometry.x,
        y: geometry.y,
        width: geometry.width,
        height: geometry.height,
        parent: attributes.parent,
        text: tag.text,
      })
      continue
    }
    const geometry = geometryOf(attributes, tag.inner)
    edges.push({
      id,
      label,
      source: attributes.source,
      target: attributes.target,
      points: geometry.points,
      sourcePoint: geometry.sourcePoint,
      targetPoint: geometry.targetPoint,
      style: parseStyle(attributes.style),
      text: tag.text,
    })
  }
  return { nodes, edges, layers, model }
}

/** Bounding box of every node, for SVG scaling. */
export function diagramBounds(diagram, padding = 40) {
  if (diagram.nodes.length === 0) {
    return { x: 0, y: 0, width: 320, height: 200 }
  }
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (const node of diagram.nodes) {
    minX = Math.min(minX, node.x)
    minY = Math.min(minY, node.y)
    maxX = Math.max(maxX, node.x + node.width)
    maxY = Math.max(maxY, node.y + node.height)
  }
  for (const edge of diagram.edges) {
    for (const point of edge.points) {
      minX = Math.min(minX, point.x)
      minY = Math.min(minY, point.y)
      maxX = Math.max(maxX, point.x)
      maxY = Math.max(maxY, point.y)
    }
  }
  return {
    x: minX - padding,
    y: minY - padding,
    width: maxX - minX + padding * 2,
    height: maxY - minY + padding * 2,
  }
}

/** A compact, model-facing description of one page. */
export function describeDiagram(xml, maxNodes = 60, maxEdges = 80) {
  const diagram = readDiagram(xml)
  const inbound = new Map()
  const outbound = new Map()
  for (const edge of diagram.edges) {
    if (edge.source !== undefined) outbound.set(edge.source, (outbound.get(edge.source) ?? 0) + 1)
    if (edge.target !== undefined) inbound.set(edge.target, (inbound.get(edge.target) ?? 0) + 1)
  }
  return {
    nodes: diagram.nodes.length,
    edges: diagram.edges.length,
    nodeList: diagram.nodes.slice(0, maxNodes).map((node) => ({
      id: node.id,
      label: node.label,
      shape: shapeOf(node.style),
      in: inbound.get(node.id) ?? 0,
      out: outbound.get(node.id) ?? 0,
    })),
    edgeList: diagram.edges.slice(0, maxEdges).map((edge) => ({
      id: edge.id,
      from: edge.source,
      to: edge.target,
      label: edge.label,
    })),
    truncatedNodes: Math.max(0, diagram.nodes.length - maxNodes),
    truncatedEdges: Math.max(0, diagram.edges.length - maxEdges),
  }
}

/**
 * draw.io `shape=` names folded onto the primitives the preview draws.
 *
 * draw.io names its stencils after the stencil (`cylinder3`, `umlActor`), while
 * the preview only has a handful of primitives; one table keeps the two in step
 * instead of letting each call site guess.
 */
const SHAPE_ALIASES = {
  cylinder3: 'cylinder',
  cylinder: 'cylinder',
  database: 'cylinder',
  umlactor: 'actor',
  actor: 'actor',
  'stencil.actor': 'actor',
  note: 'note',
  document: 'document',
  cloud: 'cloud',
  hexagon2: 'hexagon',
}

/**
 * Primitives the preview can draw. An explicit `shape=` naming one of these
 * wins over the flags, because draw.io writes both: `ellipse;shape=cloud` is a
 * cloud, not an ellipse.
 */
const KNOWN_PRIMITIVES = new Set([
  'ellipse',
  'rhombus',
  'rounded',
  'text',
  'hexagon',
  'parallelogram',
  'cylinder',
  'actor',
  'note',
  'document',
  'cloud',
])

/** The draw.io shape a style selects, normalized for the preview renderer. */
export function shapeOf(style) {
  if (typeof style.shape === 'string' && style.shape.length > 0) {
    const normalized = SHAPE_ALIASES[style.shape.toLowerCase()] ?? style.shape.toLowerCase()
    if (KNOWN_PRIMITIVES.has(normalized)) return normalized
  }
  if (style.ellipse === true) return 'ellipse'
  if (style.rhombus === true) return 'rhombus'
  if (style.text === true) return 'text'
  if (style.rounded === '1' || style.rounded === true) return 'rounded'
  return 'rectangle'
}
